-- FERTINI fresh PostgreSQL 17 schema, constructed from structural XAMPP DDL ONLY.

-- NO previous customers, orders, payments or credentials are imported.

-- Dedicated Neon branch only; portable to any PostgreSQL 17 instance.



CREATE TABLE IF NOT EXISTS "admin_notifications" (
  "id" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "type" varchar(50) NOT NULL,
  "title" varchar(255) NOT NULL,
  "message" text,
  "entity_type" varchar(50),
  "entity_id" BIGINT,
  "is_read" INTEGER NOT NULL DEFAULT 0,
  "created_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS "brands" (
  "id" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" varchar(120) NOT NULL,
  "slug" varchar(160) NOT NULL,
  "description" text,
  "logo_url" varchar(500),
  "country" varchar(100),
  "status" VARCHAR(40) NOT NULL DEFAULT 'ACTIVE',
  "created_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "deleted_at" TIMESTAMP,
  "is_active" INTEGER NOT NULL DEFAULT 1
);

CREATE TABLE IF NOT EXISTS "carts" (
  "id" char(36) NOT NULL PRIMARY KEY,
  "customer_id" BIGINT,
  "status" VARCHAR(40) NOT NULL DEFAULT 'ACTIVE',
  "created_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS "cart_items" (
  "id" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "cart_id" char(36) NOT NULL,
  "product_id" BIGINT NOT NULL,
  "variant_id" BIGINT NOT NULL,
  "quantity" INTEGER NOT NULL DEFAULT 1,
  "unit_price" NUMERIC(12,2) NOT NULL,
  "created_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS "categories" (
  "id" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" varchar(120) NOT NULL,
  "slug" varchar(160) NOT NULL,
  "description" text,
  "image_url" varchar(500),
  "created_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "deleted_at" TIMESTAMP,
  "is_active" INTEGER NOT NULL DEFAULT 1
);

CREATE TABLE IF NOT EXISTS "categories_backup" (
  "id" BIGINT NOT NULL DEFAULT 0,
  "parent_id" BIGINT,
  "name" varchar(120) NOT NULL,
  "slug" varchar(160) NOT NULL,
  "description" text,
  "image_url" varchar(500),
  "created_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "deleted_at" TIMESTAMP,
  "is_active" INTEGER NOT NULL DEFAULT 1
);

CREATE TABLE IF NOT EXISTS "categories_old" (
  "id" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "parent_id" BIGINT,
  "name" varchar(120) NOT NULL,
  "slug" varchar(160) NOT NULL,
  "description" text,
  "image_url" varchar(500),
  "created_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "deleted_at" TIMESTAMP,
  "is_active" INTEGER NOT NULL DEFAULT 1
);

CREATE TABLE IF NOT EXISTS "category_parents" (
  "id" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "category_id" BIGINT NOT NULL,
  "parent_id" BIGINT NOT NULL,
  "created_at" timestamp NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS "coupons" (
  "id" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "code" varchar(80) NOT NULL,
  "title" varchar(150),
  "description" text,
  "discount_type" VARCHAR(40) NOT NULL,
  "discount_value" NUMERIC(12,2) NOT NULL,
  "min_order_amount" NUMERIC(12,2),
  "max_discount_amount" NUMERIC(12,2),
  "usage_limit" INTEGER,
  "used_count" INTEGER NOT NULL DEFAULT 0,
  "starts_at" TIMESTAMP,
  "expires_at" TIMESTAMP,
  "status" VARCHAR(40) NOT NULL DEFAULT 'ACTIVE',
  "created_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS "customers" (
  "id" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "first_name" varchar(100) NOT NULL,
  "last_name" varchar(100) NOT NULL,
  "mobile" varchar(20) NOT NULL,
  "email" varchar(191),
  "password_hash" varchar(255) NOT NULL,
  "role" VARCHAR(40) NOT NULL DEFAULT 'USER',
  "is_active" INTEGER NOT NULL DEFAULT 1,
  "last_login_at" TIMESTAMP,
  "created_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS "customer_addresses" (
  "id" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "customer_id" BIGINT NOT NULL,
  "province" varchar(100) NOT NULL,
  "city" varchar(100) NOT NULL,
  "address" text NOT NULL,
  "plaque" varchar(20) NOT NULL,
  "floor" varchar(20),
  "unit" varchar(20),
  "postal_code" varchar(10),
  "phone" varchar(20),
  "is_default" INTEGER NOT NULL DEFAULT 1,
  "created_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS "customer_profiles" (
  "id" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "customer_id" BIGINT NOT NULL,
  "national_code" varchar(20),
  "postal_code" varchar(20),
  "province" varchar(100),
  "city" varchar(100),
  "address" text,
  "building_number" varchar(50),
  "unit" varchar(50),
  "landline_phone" varchar(30),
  "extra_description" text,
  "created_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS "orders" (
  "id" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "order_number" varchar(80) NOT NULL,
  "customer_id" BIGINT,
  "cart_id" char(36),
  "coupon_id" BIGINT,
  "status" VARCHAR(40) NOT NULL DEFAULT 'PENDING_PAYMENT',
  "payment_status" VARCHAR(40) NOT NULL DEFAULT 'UNPAID',
  "payment_intent_id" varchar(150),
  "customer_name" varchar(120) NOT NULL,
  "customer_phone" varchar(30) NOT NULL,
  "customer_landline" varchar(30),
  "customer_email" varchar(190),
  "shipping_province" varchar(100) NOT NULL,
  "shipping_city" varchar(100) NOT NULL,
  "shipping_postal_code" varchar(20),
  "shipping_address" text NOT NULL,
  "shipping_plaque" varchar(30),
  "shipping_floor" varchar(30),
  "shipping_unit" varchar(30),
  "subtotal_amount" NUMERIC(12,2) NOT NULL DEFAULT 0.00,
  "discount_amount" NUMERIC(12,2) NOT NULL DEFAULT 0.00,
  "shipping_amount" NUMERIC(12,2) NOT NULL DEFAULT 0.00,
  "total_amount" NUMERIC(12,2) NOT NULL DEFAULT 0.00,
  "notes" text,
  "payment_method" varchar(50) DEFAULT 'ONLINE',
  "customer_snapshot" TEXT,
  "admin_notes" text,
  "paid_at" TIMESTAMP,
  "shipped_at" TIMESTAMP,
  "delivered_at" TIMESTAMP,
  "cancelled_at" TIMESTAMP,
  "created_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "address_id" BIGINT
);

CREATE TABLE IF NOT EXISTS "order_items" (
  "id" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "order_id" BIGINT NOT NULL,
  "product_id" BIGINT,
  "variant_id" BIGINT,
  "product_name" varchar(190) NOT NULL,
  "variant_title" varchar(120),
  "sku" varchar(120),
  "volume_ml" INTEGER,
  "quantity" INTEGER NOT NULL,
  "unit_price" NUMERIC(12,2) NOT NULL,
  "total_price" NUMERIC(12,2) NOT NULL,
  "created_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "product_variant_id" BIGINT,
  "variant_label" varchar(120),
  "line_total" NUMERIC(12,2) NOT NULL,
  "product_snapshot" TEXT
);

CREATE TABLE IF NOT EXISTS "payments" (
  "id" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "order_id" BIGINT NOT NULL,
  "provider" varchar(80),
  "authority" varchar(190),
  "ref_id" varchar(190),
  "amount" NUMERIC(12,2) NOT NULL,
  "status" VARCHAR(40) NOT NULL DEFAULT 'PENDING',
  "paid_at" TIMESTAMP,
  "raw_response" TEXT,
  "created_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "payment_intent_id" varchar(150),
  "transaction_id" varchar(150),
  "payload" TEXT
);

CREATE TABLE IF NOT EXISTS "products" (
  "id" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "type" VARCHAR(40) NOT NULL DEFAULT 'SINGLE',
  "category_id" BIGINT,
  "scent_family_id" BIGINT,
  "parent_category_id" BIGINT,
  "name" varchar(190) NOT NULL,
  "slug" varchar(220) NOT NULL,
  "description" text,
  "scent_family" varchar(120),
  "scent_family_description" varchar(500),
  "scent_family_image" varchar(500),
  "price" NUMERIC(12,2),
  "image" varchar(500),
  "voice_file" varchar(500),
  "is_active" INTEGER NOT NULL DEFAULT 1,
  "is_featured" INTEGER NOT NULL DEFAULT 0,
  "is_best_seller" INTEGER NOT NULL DEFAULT 0,
  "created_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "deleted_at" TIMESTAMP
);

CREATE TABLE IF NOT EXISTS "product_category_links" (
  "id" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "product_id" BIGINT NOT NULL,
  "parent_id" BIGINT NOT NULL,
  "child_id" BIGINT NOT NULL,
  "created_at" timestamp NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS "product_images" (
  "id" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "product_id" BIGINT NOT NULL,
  "image_url" varchar(500) NOT NULL,
  "is_main" INTEGER NOT NULL DEFAULT 0,
  "created_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS "product_variants" (
  "id" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "product_id" BIGINT NOT NULL,
  "volume_ml" INTEGER,
  "price" NUMERIC(12,2) NOT NULL,
  "discount_price" NUMERIC(12,2),
  "stock" INTEGER NOT NULL DEFAULT 0,
  "low_stock_threshold" INTEGER NOT NULL DEFAULT 5,
  "is_default" INTEGER NOT NULL DEFAULT 0,
  "status" VARCHAR(40) NOT NULL DEFAULT 'ACTIVE',
  "created_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "deleted_at" TIMESTAMP,
  "reserved_stock_qty" INTEGER NOT NULL DEFAULT 0,
  "compare_at_price" NUMERIC(12,2),
  "stock_qty" INTEGER NOT NULL DEFAULT 0,
  "is_active" INTEGER NOT NULL DEFAULT 1
);

CREATE TABLE IF NOT EXISTS "product_variant_images" (
  "id" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "product_variant_id" BIGINT NOT NULL,
  "image_url" varchar(500) NOT NULL,
  "alt_text" varchar(190),
  "sort_order" INTEGER NOT NULL DEFAULT 0,
  "is_main" INTEGER NOT NULL DEFAULT 0,
  "created_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS "reviews" (
  "id" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "user_id" BIGINT,
  "product_id" BIGINT NOT NULL,
  "order_id" BIGINT,
  "rating" INTEGER NOT NULL DEFAULT 0,
  "title" varchar(190),
  "comment" text,
  "status" VARCHAR(40) NOT NULL DEFAULT 'PENDING',
  "created_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "is_approved" INTEGER NOT NULL DEFAULT 0,
  "admin_reply" TEXT
);

CREATE TABLE IF NOT EXISTS "scent_families" (
  "id" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" varchar(120) NOT NULL,
  "slug" varchar(160) NOT NULL,
  "image_url" varchar(500),
  "is_active" INTEGER NOT NULL DEFAULT 1,
  "sort_order" INTEGER NOT NULL DEFAULT 0,
  "created_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS "sliders" (
  "id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "product_id" BIGINT,
  "placement" VARCHAR(40) NOT NULL DEFAULT 'HOME',
  "title" varchar(255) NOT NULL,
  "slug" varchar(255) NOT NULL,
  "image_url" text NOT NULL,
  "link" varchar(500),
  "is_active" INTEGER NOT NULL DEFAULT 1,
  "created_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "deleted_at" timestamp NULL
);

CREATE TABLE IF NOT EXISTS "users" (
  "id" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "full_name" varchar(120) NOT NULL,
  "email" varchar(255),
  "phone" varchar(30),
  "password_hash" varchar(255) NOT NULL,
  "role" VARCHAR(40) NOT NULL DEFAULT 'USER',
  "status" VARCHAR(40) NOT NULL DEFAULT 'ACTIVE',
  "phone_verified_at" TIMESTAMP,
  "last_login_at" TIMESTAMP,
  "created_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "deleted_at" TIMESTAMP,
  "is_active" INTEGER NOT NULL DEFAULT 1
);

CREATE TABLE IF NOT EXISTS "user_addresses" (
  "id" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "user_id" BIGINT NOT NULL,
  "title" varchar(100),
  "receiver_name" varchar(120) NOT NULL,
  "receiver_phone" varchar(30) NOT NULL,
  "province" varchar(100) NOT NULL,
  "city" varchar(100) NOT NULL,
  "postal_code" varchar(20),
  "address_line" text NOT NULL,
  "plaque" varchar(30),
  "unit" varchar(30),
  "is_default" INTEGER NOT NULL DEFAULT 0,
  "created_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS "wishlist_items" (
  "id" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "user_id" BIGINT NOT NULL,
  "product_id" BIGINT NOT NULL,
  "created_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);

ALTER TABLE "products" ADD COLUMN IF NOT EXISTS "status" VARCHAR(12) NOT NULL DEFAULT 'ACTIVE';

ALTER TABLE "product_images" ADD COLUMN IF NOT EXISTS "sort_order" INTEGER NOT NULL DEFAULT 0;

ALTER TABLE "product_images" ADD COLUMN IF NOT EXISTS "alt_text" VARCHAR(255);

CREATE TABLE IF NOT EXISTS "storefront_content" ("id" SMALLINT PRIMARY KEY, "content_json" TEXT NOT NULL, "updated_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);

CREATE TABLE IF NOT EXISTS "user_profiles" ("id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, "user_id" BIGINT NOT NULL UNIQUE, "national_code" VARCHAR(20), "postal_code" VARCHAR(20), "province" VARCHAR(100), "city" VARCHAR(100), "address" TEXT, "building_number" VARCHAR(50), "unit" VARCHAR(50), "landline_phone" VARCHAR(30), "extra_description" TEXT, "created_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);

CREATE UNIQUE INDEX IF NOT EXISTS "uq_cart_items_cart_id_variant_id" ON "cart_items" ("cart_id","variant_id");

CREATE UNIQUE INDEX IF NOT EXISTS "uq_customers_mobile" ON "customers" ("mobile");

CREATE UNIQUE INDEX IF NOT EXISTS "uq_customers_email" ON "customers" ("email");

CREATE UNIQUE INDEX IF NOT EXISTS "uq_users_email" ON "users" ("email");

CREATE UNIQUE INDEX IF NOT EXISTS "uq_products_slug" ON "products" ("slug");

CREATE UNIQUE INDEX IF NOT EXISTS "uq_categories_slug" ON "categories" ("slug");

CREATE UNIQUE INDEX IF NOT EXISTS "uq_scent_families_slug" ON "scent_families" ("slug");

CREATE UNIQUE INDEX IF NOT EXISTS "uq_scent_families_name" ON "scent_families" ("name");

CREATE UNIQUE INDEX IF NOT EXISTS "uq_orders_order_number" ON "orders" ("order_number");

CREATE UNIQUE INDEX IF NOT EXISTS "uq_category_parents_category_id_parent_id" ON "category_parents" ("category_id","parent_id");

CREATE UNIQUE INDEX IF NOT EXISTS "uq_product_category_links_product_id_parent_id_child_id" ON "product_category_links" ("product_id","parent_id","child_id");

CREATE UNIQUE INDEX IF NOT EXISTS "uq_product_variants_product_id_volume_ml" ON "product_variants" ("product_id","volume_ml");

CREATE UNIQUE INDEX IF NOT EXISTS "uq_customer_profiles_customer_id" ON "customer_profiles" ("customer_id");

CREATE UNIQUE INDEX IF NOT EXISTS "uq_admin_notifications_type_entity_type_entity_id" ON "admin_notifications" ("type","entity_type","entity_id");

CREATE UNIQUE INDEX IF NOT EXISTS "uq_payments_payment_intent_id" ON "payments" ("payment_intent_id");

CREATE UNIQUE INDEX IF NOT EXISTS "uq_sliders_slug" ON "sliders" ("slug");

CREATE TABLE IF NOT EXISTS "support_threads" (
 "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 "visitor_name" VARCHAR(70) NOT NULL,
 "subject" VARCHAR(120) NOT NULL,
 "token_hash" VARCHAR(64) NOT NULL UNIQUE,
 "status" VARCHAR(16) NOT NULL DEFAULT 'OPEN',
 "created_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
 "updated_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS "support_threads_status_updated_idx" ON "support_threads" ("status","updated_at");

CREATE TABLE IF NOT EXISTS "support_messages" (
 "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 "thread_id" BIGINT NOT NULL REFERENCES "support_threads"("id") ON DELETE CASCADE,
 "role" VARCHAR(16) NOT NULL,
 "body" TEXT NOT NULL,
 "created_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS "support_messages_thread_created_idx" ON "support_messages" ("thread_id","created_at");

CREATE TABLE IF NOT EXISTS "support_faq" (
 "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 "question" TEXT NOT NULL,
 "answer" TEXT,
 "published" BOOLEAN NOT NULL DEFAULT FALSE,
 "created_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
 "updated_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS "support_faq_published_idx" ON "support_faq" ("published","updated_at");

CREATE TABLE IF NOT EXISTS "support_settings" (
 "id" INTEGER PRIMARY KEY DEFAULT 1 CHECK ("id" = 1),
 "welcome" TEXT NOT NULL DEFAULT 'به گالری فرتینی خوش آمدید؛ چه رایحه‌ای در ذهن دارید؟',
 "expected_response" TEXT NOT NULL DEFAULT 'مشاور فرتینی در اولین فرصت پاسخ می‌دهد.',
 "working_hours" TEXT NOT NULL DEFAULT '',
 "enabled" BOOLEAN NOT NULL DEFAULT TRUE,
 "updated_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX IF NOT EXISTS "products_scent_family_idx" ON "products"("scent_family_id");
